"""Stage 9: late-lot robustness. --train fits hold-out models without the late lot; --score reads the test split once."""
import argparse, importlib.util, json
from pathlib import Path
import joblib, numpy as np, pandas as pd
import common as C

SRC = Path(__file__).resolve().parent
HOLD_FS = ["all106", "shape16", "sizefree7", "sizefree22"]
UNTUNED = ("sizefree7", "sizefree22")    # never tuned: they take the all106 point by design
CONF = 0.95


def _load(fname, folder=SRC):
    """Import a numbered stage module, or freeze from tools, without running it."""
    spec = importlib.util.spec_from_file_location(fname.replace(".py", "").replace("0", "m", 1), folder / fname)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def hold_dir():
    d = C.MODELS / "holdout"
    d.mkdir(parents=True, exist_ok=True)
    return d


def hgb_key(fs):
    return "hgb:all106" if fs in UNTUNED else f"hgb:{fs}"


def params_from(name):
    """The tuned point an arm borrowed, blank when it used its own, so the group can disclose it."""
    fs = name.split(":")[-1]
    return hgb_key(fs) if "hgb" in name and fs in UNTUNED else ""


def frozen_configs():
    """The tuned settings for every hold-out fit, or a stop naming what is missing. There is no default to fall back on."""
    pp, pc = C.RES / "baselines" / "best_params.json", C.RES / "neural" / "best_config.json"
    gone = [str(p) for p in (pp, pc) if not p.exists()]
    best = json.loads(pp.read_text()) if pp.exists() else {}
    cfg = json.loads(pc.read_text()) if pc.exists() else {}
    if pp.exists(): gone += [f"{pp.name}: {k}" for k in sorted({hgb_key(fs) for fs in HOLD_FS}) if not best.get(k)]
    if pc.exists() and not cfg.get("cnn"): gone.append(f"{pc.name}: cnn")
    if gone: raise SystemExit("cannot train hold-out models, missing:\n  " + "\n  ".join(gone))
    return {fs: best[hgb_key(fs)] for fs in HOLD_FS}, cfg["cnn"]


def holdout_frames(tr, va):
    """Train and validation without the late lot: the only rows a hold-out model may see."""
    return tr[tr.lot != "late"].reset_index(drop=True), va[va.lot != "late"].reset_index(drop=True)


def table_jobs(tr, trh):
    """(saved stem, featureset, training rows) for every table model: hold-out arms on trh, the full-data reference on tr."""
    return [(f"hgb__{fs}", fs, trh) for fs in HOLD_FS] + [(f"full_hgb__{fs}", fs, tr) for fs in UNTUNED]


def read_needs(tr, va):
    """Every file the --score path loads, plus the image folders it reads after the test read."""
    hd = C.MODELS / "holdout"
    return ([hd / f"hgb__{fs}.joblib" for fs in HOLD_FS] + [hd / f"full_hgb__{fs}.joblib" for fs in UNTUNED]
            + [d / f"cnn_seed{s}.pt" for d in (hd, C.MODELS) for s in C.SEEDS]
            + [hd / "routing.json", hd / "gate_table.joblib", hd / "gate_image.joblib", C.MODELS / "hgb_all106.joblib", C.MODELS / "baselines" / "hgb__shape16.joblib", C.cache_path()]
            + [C.pred_path("cnn", "image", s, "test") for s in C.SEEDS]
            + sorted({Path(p).parent for p in pd.concat([tr.path, va.path])}))


def preflight(paths):
    """Names everything missing and stops, before a test read is spent."""
    gone = [str(p) for p in paths if not p.exists()]
    if gone: raise SystemExit("cannot read test, missing:\n  " + "\n  ".join(gone))


def control_row(k, P, late_te, ref):
    """Largest stage 7 against stage 9 gap on the grains both hold. A record only: the read is spent, so it never stops the stage."""
    ref = ref.set_index("grain_id")
    keep = late_te.grain_id.isin(ref.index).to_numpy()
    if not keep.any(): return dict(seed=k, n=0, max_abs_diff=np.nan, argmax_equal=False)
    Pr = C.probs(ref.loc[late_te.grain_id[keep]].reset_index())
    return dict(seed=k, n=int(keep.sum()), max_abs_diff=float(np.abs(P[keep] - Pr).max()), argmax_equal=bool((P[keep].argmax(1) == Pr.argmax(1)).all()))


# ---- grey-world correction -----------------------------------------------------------
def grey_world_gains(img, mask):
    """Per-channel gains from grain pixels only: gain_c = mean over mask of all channels / mean over mask of channel c."""
    if mask is None or not mask.any():
        return np.ones(3)
    px = img[mask].astype(np.float64)
    m = px.mean(0)
    return px.mean() / np.maximum(m, 1e-9)


def apply_gains(img, g):
    return np.clip(np.rint(img.astype(np.float64) * g), 0, 255).astype(np.uint8)


def read250(path):
    from PIL import Image
    a = np.asarray(Image.open(path).convert("RGB"))
    assert a.shape == (250, 250, 3), f"{path}: {a.shape}"
    return a


def mask_means(img):
    m = C.grain_mask(img)
    return (img[m] if m is not None and m.any() else img.reshape(-1, 3)).astype(np.float64).mean(0)


# ---- training ------------------------------------------------------------------------
def same_run(ck, run, ids):
    """A saved seed counts only if it came from these settings and these rows."""
    return ck.get("run") == run and ck.get("train_ids") == ids


def reusable(path, run, ids):
    """True only for a complete file from this same run. A missing, torn or stale file is retrained, never reused."""
    if not path.exists(): return False
    import torch
    try:
        return same_run(torch.load(path, map_location="cpu", weights_only=False), run, ids)
    except Exception:
        return False


def cnn_record(m, cfg, run, mean, std, ids):
    """What a hold-out CNN file holds. cfg is what load_cnn builds from; run is everything that shaped the weights."""
    return {"state": m.state_dict(), "cfg": {"width": cfg["width"], "dropout": cfg["dropout"]}, "run": run, "mean": mean, "std": std, "train_ids": ids}


def holdout_cnn(N, s, cfg, trh, vah, stats, path):
    """One seed's hold-out CNN. A file from this same run is reused, so a crash after the CNN loop does not cost the 1.98 h again."""
    run, ids = {**cfg, "epochs": N.EP_CNN, "patience": N.PAT_CNN}, trh.grain_id.tolist()
    if reusable(path, run, ids):
        print(f"reusing {path.name}: same settings, same training rows", flush=True)
        return C.load_cnn(path)
    m, _, mean, std = N.train_cnn(cfg, s, trh, vah, N.EP_CNN, N.PAT_CNN, f"holdout_cnn_seed{s}", stats=stats)
    import torch
    torch.save(cnn_record(m, cfg, run, mean, std, ids), path)
    return m, mean, std


def fit_tables(B, jobs, params, hd):
    """Fits each table model and saves with it the rows it was fitted on."""
    for stem, fs, rows in jobs:
        pipe = B.build("hgb", params[fs]).fit(*C.xy(rows, fs))
        joblib.dump({"pipe": pipe, "cols": C.features(fs), "params": params[fs], "params_from": hgb_key(fs), "train_ids": rows.grain_id.tolist()}, hd / f"{stem}.joblib")


def controls_stand():
    """Hold-out training costs 1.98 h and freeze would refuse a failed control after it, so the same check runs first. Smoke runs no --control, as in freeze."""
    if C.SMOKE: return
    bad = _load("freeze.py", SRC.parent / "tools").control_faults()
    if bad: raise SystemExit("cannot train hold-out, controls:\n  " + "\n  ".join(bad))


def train():
    params, cfg = frozen_configs()                  # first line: no fit on a missing setting
    controls_stand()
    B, N = _load("05_baselines.py"), _load("06_neural.py")
    tr, va = C.load_split("train"), C.load_split("val")
    trh, vah = holdout_frames(tr, va)
    print(f"hold-out train {len(trh)} val {len(vah)} (late dropped: {len(tr) - len(trh)} + {len(va) - len(vah)})", flush=True)
    hd = hold_dir()
    fit_tables(B, table_jobs(tr, trh), params, hd)
    stats = N.chan_stats(trh)
    emb = {}
    for s in C.SEEDS:
        m, mean, std = holdout_cnn(N, s, cfg, trh, vah, stats, hd / f"cnn_seed{s}.pt")
        if s == 0:                                  # embeddings come from the model in hand, trained or rebuilt from its file
            Pv, Ev = N.cnn_eval(m, mean, std, vah)
            _, Et = N.cnn_eval(m, mean, std, trh)
            emb = {"tr": Et, "va": Ev, "Pv": Pv}
    # hold-out routing, refit on hold-out validation only
    y = vah.y.to_numpy()
    Ph = joblib.load(hd / "hgb__all106.joblib")["pipe"].predict_proba(vah[C.ALL106])
    R = {}
    for nm, P, tgt in [("hgb", Ph, 0.9995), ("cnn", emb["Pv"], 0.99)]:
        T = C.temperature(P, y)
        Pk = C.apply_temp(P, T)
        R[nm] = {"temperature": T, "target_accuracy": tgt, "floor": C.floor_for(Pk.max(1), Pk.argmax(1) == y, tgt)}
    gt = C.Gate().fit(trh[C.ALL106].to_numpy(np.float64), trh.y.to_numpy(), vah[C.ALL106].to_numpy(np.float64))
    gi = C.Gate().fit(emb["tr"], trh.y.to_numpy(), emb["va"])
    joblib.dump(gt, hd / "gate_table.joblib"); joblib.dump(gi, hd / "gate_image.joblib")
    R["gate_table"], R["gate_image"] = {"cut": gt.cut}, {"cut": gi.cut}
    (hd / "routing.json").write_text(json.dumps(R, indent=1)); C.wrote(hd / "routing.json")


# ---- scoring -------------------------------------------------------------------------
def recall_row(name, tag, P, y):
    ok = P.argmax(1) == y
    lo, hi = C.wilson(int(ok.sum()), len(ok))
    cf = P.max(1)
    return dict(model=name, subset=tag, n=len(y), recall=float(ok.mean()), ci_low=lo, ci_high=hi, mean_confidence=float(cf.mean()),
                confidently_wrong=int(((cf >= CONF) & ~ok).sum()))


def per_class_sample(df, n):
    return pd.concat([d.sample(min(len(d), n), random_state=C.SEED) for _, d in df.groupby("y")]).reset_index(drop=True)


def late_rows(name, P, y, is_te):
    """Only hold-out models never saw a late grain; every other model is scored on the test subset alone."""
    rows = [recall_row(name, "late_test", P[is_te], y[is_te])]
    if name.startswith("holdout_"):
        rows.insert(0, recall_row(name, "late_all", P, y))
    return rows


def read_test():
    """The single gated test read of this stage. An infinite cell becomes a missing one, which every pipeline imputes; left in, the first imputer raises right after the read."""
    df = C.load_split("test")
    print(f"test read: {len(df)} grains, {int(np.isinf(df[C.ALL106].to_numpy(np.float64)).sum())} infinite cells made missing", flush=True)
    return df.replace([np.inf, -np.inf], np.nan)


def score():
    N = _load("08_routing.py")
    hd = hold_dir()
    out = C.stage_dir("robustness")
    tr, va = C.load_split("train"), C.load_split("val")
    if not (pd.concat([tr.lot, va.lot]) == "late").any():
        raise SystemExit("cannot read test: no late grains in train or validation, so the late models would have no rows to score")
    preflight(read_needs(tr, va))                     # names every missing file before the read is spent
    score_late(N, hd, out, tr, va, read_test())


def score_late(N, hd, out, tr, va, te):
    """Everything after the read. Apart from score() so a test can drive the real grey_world call on made-up rows."""
    allsplit = pd.concat([tr, va, te], ignore_index=True).drop_duplicates("grain_id")   # smoke: te is validation again
    late = allsplit[allsplit.lot == "late"].reset_index(drop=True)
    is_te = late.grain_id.isin(te.grain_id).to_numpy()
    late_te = late[is_te].reset_index(drop=True)
    assert not set(late_te.grain_id) & set(tr.grain_id), "a scored grain is in train"
    print(f"late grains: all {len(late)}, test {len(late_te)}", flush=True)
    y = late.y.to_numpy()
    rows, P_ref = [], {}

    def add(name, P):
        P_ref[name] = P
        rows.extend(r | {"params_from": params_from(name)} for r in late_rows(name, P, y, is_te))

    for fs in HOLD_FS:
        add(f"holdout_hgb:{fs}", joblib.load(hd / f"hgb__{fs}.joblib")["pipe"].predict_proba(late[C.features(fs)]))
    for fs in UNTUNED:
        add(f"full_hgb:{fs}", joblib.load(hd / f"full_hgb__{fs}.joblib")["pipe"].predict_proba(late[C.features(fs)]))
    add("full_hgb:all106", joblib.load(C.MODELS / "hgb_all106.joblib")["pipe"].predict_proba(late[C.ALL106]))
    add("full_hgb:shape16", joblib.load(C.MODELS / "baselines" / "hgb__shape16.joblib")["pipe"].predict_proba(late[C.features("shape16")]))
    emb_h = None
    for s in C.SEEDS:
        P, E = C.cnn_on_df(hd / f"cnn_seed{s}.pt", late)
        add(f"holdout_cnn:seed{s}", P)
        if s == 0: emb_h = E
        add(f"full_cnn:seed{s}", C.cnn_on_df(C.MODELS / f"cnn_seed{s}.pt", late)[0])
    R = pd.DataFrame(rows)
    R.to_csv(out / "late_recall.csv", index=False); C.wrote(out / "late_recall.csv")
    print(R.round(4).to_string(index=False))

    # confidence chain on the late lot with the hold-out routing
    rt = json.loads((hd / "routing.json").read_text())
    gt, gi = joblib.load(hd / "gate_table.joblib"), joblib.load(hd / "gate_image.joblib")
    Ph, Pc = C.apply_temp(P_ref["holdout_hgb:all106"], rt["hgb"]["temperature"]), C.apply_temp(P_ref["holdout_cnn:seed0"], rt["cnn"]["temperature"])
    unf = gt.unfamiliar(late[C.ALL106].to_numpy(np.float64)) | gi.unfamiliar(emb_h)
    route, ans, key = N.chain(Ph, Pc, rt["hgb"]["floor"], rt["cnn"]["floor"], unf)
    ch = []
    for subset, m in [("late_all", np.ones(len(y), bool)), ("late_test", is_te)]:
        for r in ["hgb", "cnn", "unsure", "unfamiliar"]:
            k = m & (route == r)
            ch.append(dict(subset=subset, route=r, grains=int(k.sum()), share=float(k.sum() / max(m.sum(), 1)),
                           errors=int((ans[k] != y[k]).sum()) if r in ("hgb", "cnn") else np.nan))
        a = m & np.isin(route, ["hgb", "cnn"])
        ch.append(dict(subset=subset, route="answered_total", grains=int(a.sum()), share=float(a.sum() / max(m.sum(), 1)), errors=int((ans[a] != y[a]).sum())))
    pd.DataFrame(ch).to_csv(out / "late_chain.csv", index=False); C.wrote(out / "late_chain.csv")

    grey_world(late_te, tr, va, out)


def gain_rows(samp, G):
    """r(gain, log AREA) per class. A channel with no answer fails the check: np.max carries a nan through, where Python's max can drop it depending on its place."""
    cr = []
    for k in range(5):
        m = (samp.y == k).to_numpy()
        la = np.log(samp.loc[m, "AREA"].to_numpy(np.float64))
        r = [float(np.corrcoef(G[m, c], la)[0, 1]) for c in range(3)]
        top = float(np.max(np.abs(r)))
        cr.append(dict(**{"class": C.CLASSES[k]}, n=int(m.sum()), r_R=r[0], r_G=r[1], r_B=r[2], max_abs_r=top, passes_abs_lt_0_1=top < 0.1))
    return cr


def grey_world(late_te, tr, va, out):
    from sklearn.ensemble import HistGradientBoostingClassifier as HGB
    # 1. is the gain independent of grain size? r(gain, log AREA) per class, on a train+val sample
    samp = per_class_sample(pd.concat([tr, va]), 1000)
    G = np.array([grey_world_gains(im, C.grain_mask(im)) for im in (read250(p) for p in samp.path)])
    pd.DataFrame(gain_rows(samp, G)).to_csv(out / "greyworld_gain_vs_area.csv", index=False); C.wrote(out / "greyworld_gain_vs_area.csv")

    # 1b. table means vs mask means on a stratified 5000-grain train sample
    ms = per_class_sample(tr, 1000)
    MM = np.array([mask_means(read250(p)) for p in ms.path])
    mcr = []
    for c, col in enumerate(["meanRR", "meanRG", "meanRB"]):
        t = ms[col].to_numpy(np.float64)
        mcr.append(dict(channel="RGB"[c], n=len(ms), pearson=float(np.corrcoef(t, MM[:, c])[0, 1]), median_abs_diff=float(np.median(np.abs(t - MM[:, c])))))
    pd.DataFrame(mcr).to_csv(out / "mean_colour_check.csv", index=False); C.wrote(out / "mean_colour_check.csv")

    if late_te.empty:                  # only a broken split gets here; parts 1 and 1b stand and greyworld_results.csv stays absent
        print("no late test grains: tint arms not scored", flush=True)
        return

    # 2. mean-colour model, raw vs corrected image means on the late test grains (it was fitted on train)
    mcm = HGB(random_state=C.SEED, early_stopping=False, max_iter=150).fit(MM, ms.y.to_numpy())   # fitted on mask_means, same measure as scoring
    y = late_te.y.to_numpy()
    imgs = [read250(p) for p in late_te.path]
    gains = [grey_world_gains(im, C.grain_mask(im)) for im in imgs]
    raw_m = np.array([mask_means(im) for im in imgs])
    cor = [apply_gains(im, g) for im, g in zip(imgs, gains)]
    cor_m = np.array([mask_means(im) for im in cor])
    res = [dict(arm="mean_colour_model", variant="raw", n=len(y), accuracy=float((mcm.predict(raw_m) == y).mean())),
           dict(arm="mean_colour_model", variant="grey_world", n=len(y), accuracy=float((mcm.predict(cor_m) == y).mean()))]

    # 3. frozen CNN seeds on raw (gain 1, control) and corrected late test images, same 250px -> 128px path
    ctl = []
    for k in C.SEEDS:
        m, mean, std = C.load_cnn(C.MODELS / f"cnn_seed{k}.pt")
        for variant, arr in [("raw_same_path", imgs), ("grey_world", cor)]:
            r128 = np.stack([C.resize128(a) for a in arr])
            P, _ = C.run_cnn(m, mean, std, lambda a, b: r128[a:b], len(r128))
            res.append(dict(arm=f"cnn_seed{k}", variant=variant, n=len(y), accuracy=float((P.argmax(1) == y).mean())))
            if variant == "raw_same_path":
                ref = C.load_preds("cnn", "image", k, "test")
                if ref is not None:
                    ctl.append(control_row(k, P, late_te, ref))
    pd.DataFrame(res).to_csv(out / "greyworld_results.csv", index=False); C.wrote(out / "greyworld_results.csv")
    pd.DataFrame(ctl).to_csv(out / "greyworld_control.csv", index=False); C.wrote(out / "greyworld_control.csv")
    print(pd.DataFrame(res).round(4).to_string(index=False)); print(pd.DataFrame(ctl).to_string(index=False))


def main():
    ap = argparse.ArgumentParser()
    g = ap.add_mutually_exclusive_group(required=True)
    g.add_argument("--train", action="store_true")
    g.add_argument("--score", action="store_true")
    a = ap.parse_args()
    train() if a.train else score()


if __name__ == "__main__":
    main()
